--   vf3000_order_code_from_catalogue_part_03  (regler 21–44, dokumentkarta, produktraden döpt om)
-- Fingeravtryck efter körning, identiska med modellen (scripts/fingerprint-rules.ts vf3000):
--   regler  44   md5 3a839ffc6f8a2c767f312177d50d18b6   villkor 6333a1eb7574f8fb72a23c854e0bc9f0
--   värden  53   md5 40f929e6c6587635dbca6943c9e23142
--   schema       md5 2079d13b059e67b45c904ee3bc838c49
-- Verifierat live: /sv/configurator/vf3000 bygger VF3130-5G1-01 (nyckelns exempel sida 292) och
-- VF3140KT-5GZD1-02 (basmonterad, sida 306), stoppar strömsparkretsen T utan ljus/spärrdiod Z.
--
-- VF: beställnyckeln enligt SMC 5 Port Solenoid Valve VF1000/3000/5000 Series (sida 292 och 306).
-- GENERERAD ur src/lib/catalog/vf.ts -- redigera inte för hand.
--
-- Rättar familjen vf3000, som hade mallen 'VF3000-{size}-{function}-{voltage}-{connection}'
-- med påhittade värden. SMC:s kod är
-- VF{serie}{funktion}{kropp}{avluftning}{tryck}{spole}-{spänning}{anslutning}{ljus}{manöver}1-{port}{gänga}-{fäste}-{special},
-- t.ex. VF3130-5G1-01 (nyckelns exempel sida 292) och VF3140KT-5GZD1-02
-- (basmonterad, sida 306). Serien VF1000/5000, kroppsmodell, avluftning,
-- högtryck, strömsparkrets, tretton elanslutningar, ljus/spärrdiod, manöver,
-- gänga, fäste och specialutförandena fanns inte alls.
--
-- SMC-VF3130-5G-02 döps om till SMC-VF3130-5G1-02F och blir monostabil.

begin;

create schema if not exists backup;
create table if not exists backup.vf3000_before_20260916 as
  select 'param' as sort, p.id::text as id, p.param_key as k, p.label as v
  from configurator_params p join configurator_families f on f.id = p.family_id
  where f.slug = 'vf3000'
  union all
  select 'value', v.id::text, v.code, v.label
  from configurator_param_values v
  join configurator_params p on p.id = v.param_id
  join configurator_families f on f.id = p.family_id
  where f.slug = 'vf3000'
  union all
  select 'family', f.id::text, f.slug, coalesce(f.order_code_template, '')
  from configurator_families f where f.slug = 'vf3000';

insert into config_schemas (schema_id, schema_json, title_sv, title_en, category_slug)
values ('SCHEMA-VF3000-V1', '{"version":"1.0","steps":[{"id":"series","step":1,"title_sv":"Serie","title_en":"Series","required":true,"type":"single_select","options":[{"v":"1","label":"VF1000 (bara 2-läges, kroppsportad, M5 eller 1/8)"},{"v":"3","label":"VF3000 (1/8 eller 1/4; underplatta 1/4 eller 3/8)"},{"v":"5","label":"VF5000 (1/4 eller 3/8; underplatta 1/4, 3/8 eller 1/2)"}]},{"id":"actuation","step":2,"title_sv":"Funktion","title_en":"Type of actuation","required":true,"type":"single_select","options":[{"v":"1","label":"2-läges, enkel magnet (monostabil)"},{"v":"2","label":"2-läges, dubbel magnet (bistabil)"},{"v":"3","label":"3-läges, stängt mittläge"},{"v":"4","label":"3-läges, avluftat mittläge"},{"v":"5","label":"3-läges, trycksatt mittläge"}]},{"id":"body","step":3,"title_sv":"Kroppsmodell","title_en":"Body model","required":true,"type":"single_select","options":[{"v":"2","label":"Kroppsportad (VF1000 och VF5000)"},{"v":"3","label":"Kroppsportad (VF3000)"},{"v":"4","label":"Basmonterad med underplatta (VF3000 och VF5000)"}]},{"id":"body_opt","step":4,"title_sv":"Pilotavluftning","title_en":"Body option (pilot exhaust)","required":true,"type":"single_select","options":[{"v":"0","label":"Pilotventilens avluftning separat (PE-port)"},{"v":"3","label":"Huvud- och pilotventil med gemensam avluftning (krävs för IP65; inte VF1000)"}]},{"id":"pressure","step":5,"title_sv":"Tryckutförande (standard är 0,7 MPa)","title_en":"Pressure specification (0.7 MPa is standard)","required":false,"type":"single_select","options":[{"v":"K","label":"Högtryckstyp 1 MPa (inte UL-listad)"}]},{"id":"coil","step":6,"title_sv":"Spole (standard är utan strömsparkrets)","title_en":"Coil specification (standard coil is default)","required":false,"type":"single_select","options":[{"v":"T","label":"Strömsparande krets (bara DC; ljus/spärrdiod Z, med DO/YO bara S)"}]},{"id":"voltage","step":7,"title_sv":"Märkspänning","title_en":"Rated voltage","required":true,"type":"single_select","options":[{"v":"5","label":"24 V DC"},{"v":"6","label":"12 V DC"},{"v":"1","label":"100 V AC 50/60 Hz"},{"v":"2","label":"200 V AC 50/60 Hz"},{"v":"3","label":"110 V AC [115 V AC] 50/60 Hz"},{"v":"4","label":"220 V AC [230 V AC] 50/60 Hz"},{"v":"7","label":"240 V AC 50/60 Hz"},{"v":"B","label":"24 V AC 50/60 Hz (CE/UKCA med alla anslutningar, som DC)"}]},{"id":"entry","step":8,"title_sv":"Elanslutning","title_en":"Electrical entry","required":true,"type":"single_select","options":[{"v":"G","label":"Grommet, kabel 300 mm"},{"v":"H","label":"Grommet, kabel 600 mm"},{"v":"L","label":"L-plugg med kabel 300 mm"},{"v":"LN","label":"L-plugg utan kabel (två stift)"},{"v":"LO","label":"L-plugg utan kontakt"},{"v":"M","label":"M-plugg med kabel 300 mm"},{"v":"MN","label":"M-plugg utan kabel (två stift)"},{"v":"MO","label":"M-plugg utan kontakt"},{"v":"D","label":"DIN-kontakt med kontaktdon (IP65)"},{"v":"DO","label":"DIN-kontakt utan kontaktdon (IP65)"},{"v":"Y","label":"DIN EN 175301-803 med kontaktdon (IP65)"},{"v":"YO","label":"DIN EN 175301-803 utan kontaktdon (IP65)"},{"v":"T","label":"Rörgängeanslutning (IP65)"}]},{"id":"light","step":9,"title_sv":"Ljus/spärrdiod","title_en":"Light/surge voltage suppressor","required":false,"type":"single_select","options":[{"v":"S","label":"Spärrdiod (bara DC)"},{"v":"Z","label":"Ljus och spärrdiod"},{"v":"R","label":"Spärrdiod, opolär (bara DC)"},{"v":"U","label":"Ljus och spärrdiod, opolär (bara DC)"}]},{"id":"override","step":10,"title_sv":"Manuell manöver (standard är olåst tryckknapp)","title_en":"Manual override (non-locking push type is standard)","required":false,"type":"single_select","options":[{"v":"D","label":"Låsbar manöver, spårskruv (tryck och vrid)"},{"v":"E","label":"Låsbar manöver, spak (tryck och vrid)"}]},{"id":"port","step":11,"title_sv":"Portstorlek (kroppsportad) eller underplatta (basmonterad)","title_en":"Port size (body ported) or sub-plate (base mounted)","required":false,"type":"single_select","options":[{"v":"M5","label":"M5 x 0,8 (bara VF1000, bara Rc-utförandet)"},{"v":"01","label":"1/8 (VF1000 och VF3000 kroppsportad)"},{"v":"02","label":"1/4 (VF3000 och VF5000; underplatta VF3000/5000)"},{"v":"03","label":"3/8 (VF5000 kroppsportad; underplatta VF3000/5000)"},{"v":"04","label":"1/2 (underplatta VF5000)"}]},{"id":"thread","step":12,"title_sv":"Gängtyp (standard är Rc)","title_en":"Thread type (Rc is standard)","required":false,"type":"single_select","options":[{"v":"F","label":"G-gänga (standard är Rc)"},{"v":"N","label":"NPT-gänga"},{"v":"T","label":"NPTF-gänga"}]},{"id":"bracket","step":13,"title_sv":"Fäste","title_en":"Bracket","required":false,"type":"single_select","options":[{"v":"F","label":"Med fäste (kroppsportad VF1000/3000; kan inte eftermonteras)"}]},{"id":"mto","step":14,"title_sv":"Specialutförande","title_en":"Made to order","required":false,"type":"single_select","options":[{"v":"X500","label":"-X500 Pilotavluftning med rörgänga M3 (kroppsportad, avluftning 0, inte med T)"},{"v":"X600","label":"-X600 TRIAC-utgång (bara AC, inte med T; inte UL-listad)"}]}]}'::jsonb,
        'SMC VF1000/3000/5000 pilotstyrd 5-portsventil, enkelventil', 'SMC VF1000/3000/5000 pilot operated 5 port solenoid valve, single unit', 'valve')
on conflict (schema_id) do update set
