  title_sv = excluded.title_sv,
  title_en = excluded.title_en;

update configurator_families set
  title = 'Pilotstyrd 5-portsventil VF1000/3000/5000, enkelventil kroppsportad eller basmonterad',
  description = 'SMC VF1000/3000/5000 pilot operated 5 port solenoid valve, single unit: 2-position single/double and 3-position closed/exhaust/pressure centre, body ported (M5–3/8) or base mounted with sub-plate (1/4–1/2), DC or AC, grommet, plug, DIN or conduit terminal.',
