  stroke_max_mm = null,
  order_code_template = 'VF{series}{actuation}{body}{body_opt}{pressure}{coil}-{voltage}{entry}{light}{override}1-{port}{thread}-{bracket}-{mto}',
  rules_schema_id = 'SCHEMA-VF3000-V1'
where slug = 'vf3000';


