delete from config_rules where schema_id = 'SCHEMA-VF3000-V1';


insert into config_rules (schema_id, severity, if_json, message_sv, message_en, goto_step)
select 'SCHEMA-VF3000-V1', r->>'severity', r->'if_json',
       r->>'message_sv', r->>'message_en', r->>'goto_step'
from jsonb_array_elements('[{"severity":"error","if_json":{"and":[{"in":[{"var":"series"},["1"]]},{"in":[{"var":"actuation"},["3","4","5"]]}]},"message_sv":"VF1000 finns bara 2-läges (1 och 2), inte 3-läges 3, 4 och 5 (sida 292).","message_en":"VF1000 exists only 2-position (1 and 2), not 3-position 3, 4 and 5 (page 292).","goto_step":"vf3000-actuation"},{"severity":"error","if_json":{"and":[{"==":[{"var":"body"},"2"]},{"in":[{"var":"series"},["3"]]}]},"message_sv":"Kroppsmodell 2 (kroppsportad) gäller VF1000 och VF5000, inte VF3000 (sida 292 och 306).","message_en":"Body model 2 (body ported) applies to VF1000 and VF5000, not VF3000 (pages 292 and 306).","goto_step":"vf3000-body"},{"severity":"error","if_json":{"and":[{"==":[{"var":"body"},"3"]},{"in":[{"var":"series"},["1","5"]]}]},"message_sv":"Kroppsmodell 3 (kroppsportad) gäller VF3000, inte VF1000 och VF5000 (sida 292 och 306).","message_en":"Body model 3 (body ported) applies to VF3000, not VF1000 and VF5000 (pages 292 and 306).","goto_step":"vf3000-body"},{"severity":"error","if_json":{"and":[{"==":[{"var":"body"},"4"]},{"in":[{"var":"series"},["1"]]}]},"message_sv":"Kroppsmodell 4 (basmonterad) gäller VF3000 och VF5000, inte VF1000 (sida 292 och 306).","message_en":"Body model 4 (base mounted) applies to VF3000 and VF5000, not VF1000 (pages 292 and 306).","goto_step":"vf3000-body"},{"severity":"error","if_json":{"and":[{"==":[{"var":"body_opt"},"3"]},{"in":[{"var":"series"},["1"]]}]},"message_sv":"Gemensam avluftning 3 finns inte för VF1000 — bara separat pilotavluftning 0 (sida 292).","message_en":"The common exhaust 3 does not exist for VF1000 — only the individual pilot exhaust 0 (page 292).","goto_step":"vf3000-body_opt"},{"severity":"error","if_json":{"and":[{"==":[{"var":"coil"},"T"]},{"in":[{"var":"voltage"},["1","2","3","4","7","B"]]}]},"message_sv":"Den strömsparande kretsen T finns bara för DC (24 eller 12 V DC), inte AC (sida 292).","message_en":"The power saving circuit T exists only for DC (24 