insert into knowledge_doc_families (source_file, family_slug, doc_title)
values ('smc-kat-vf3000.pdf', 'vf3000', 'SMC — SMC 5 Port Solenoid Valve VF1000/3000/5000 Series')
on conflict (source_file, family_slug) do update set doc_title = excluded.doc_title;


update products set
  sku = 'SMC-VF3130-5G1-02F',
  name = 'VF3130 5/2 monostabil G 1/4',
  description = 'Pilot operated 5 port solenoid valve VF3000, 2-position single (monostable), body ported G 1/4, 24 V DC, grommet 300 mm, individual pilot exhaust. Order code VF3130-5G1-02F (catalogue page 292).'
where sku = 'SMC-VF3130-5G-02';

update product_specs s set value = '5/2 monostabil (2-läges enkel magnet)'
from products p where s.product_id = p.id and p.sku = 'SMC-VF3130-5G1-02F' and s.key = 'function';

update product_specs s set value = '7'
from products p where s.product_id = p.id and p.sku = 'SMC-VF3130-5G1-02F' and s.key = 'max_pressure';

insert into product_specs (product_id, key, value)
select p.id, x.key, x.value
from products p
cross join lateral (values
  ('series', 'VF3000'),
  ('min_pressure_mpa', '0.15'),
  ('temp_range', '-10 to +50'),
  ('max_frequency_hz', '10'),
  ('power_w', '1.5'),
  ('order_code_example', 'VF3130-5G1-02F'),
  ('catalogue', 'SMC VF1000/3000/5000, How to Order sida 292 (kroppsportad) och 306 (basmonterad), data sida 293')
) as x(key, value)
where p.sku = 'SMC-VF3130-5G1-02F'
  and not exists (select 1 from product_specs y where y.product_id = p.id and y.key = x.key);


commit;

